import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, texture, mul, float, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as _placeholder } from '@/primitives';
import { createNode as _textPlaceholder } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<any>} [cinematicPrimitives]
 * @property {string} [imageUrl]
 * @property {string} [depthMapUrl]
 * @property {Array<any>} [textContent]
 * @property {Object} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {any} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, DoubleSide, Vector3 } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry – tessellated plane (64×64)
  const width = 1.6; // matches aspect 512/320
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height, 64, 64);
  geometry.rotateX(-Math.PI / 2); // face upward (optional)

  // Placeholder material; will be replaced with node texture/displacement once assets load
  const material = new MeshStandardNodeMaterial({
    side: DoubleSide,
    metalness: 0.0,
    roughness: 0.6,
    color: 0xffffff,
  });

  const mesh = new ctx.THREE.Mesh(geometry, material);
  root.add(mesh);

  // Store references for cleanup
  const resources = {
    textures: [],
    material,
    geometry,
    timelines: [],
    primitives: [],
    originalY: mesh.position.y,
  };

  // Load image texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      resources.textures.push(tex);
      // Build node graph for color
      const texNode = texture(uniform(tex), uv());
      material.colorNode = texNode;
    });
  }

  // Load depth map for displacement
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      resources.textures.push(depthTex);
      const depthNode = texture(uniform(depthTex), uv());
      // Use the red channel as height, scale subtly
      const dispScale = float(0.2);
      material.displacementNode = mul(depthNode.r, dispScale);
    });
  }

  // ---- Interaction Handlers ----
  const handlers = {};

  // Hover lift (rise‑in) – subtle 0.15 units upward
  let hoverTween = null;
  handlers.hover = (enter) => {
    if (enter) {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(mesh.position, {
        y: resources.originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
      resources.timelines.push(hoverTween);
    } else {
      if (hoverTween) hoverTween.kill();
      const backTween = gsap.to(mesh.position, {
        y: resources.originalY,
        duration: 0.4,
        ease: 'power3.out',
      });
      resources.timelines.push(backTween);
    }
  };

  // Click – emit selection event (and placeholder navigation)
  handlers.click = () => {
    ctx.emit('hub-features.select');
    // Example navigation payload (could be enriched by data binding later)
    ctx.emit('navigate', { to: 'hub-features' });
  };

  // Attach handlers to userData
  root.userData.handlers = handlers;

  // ---- Cinematic Primitives ----
  const appliedPrimitives = [];

  if (Array.isArray(config.cinematicPrimitives) && config.cinematicPrimitives.length) {
    for (const prim of config.cinematicPrimitives) {
      const result = ctx.primitives[prim.name](root, prim.params);
      appliedPrimitives.push(result);
    }
  } else {
    // Ensure a gentle parallax effect if none supplied
    if (ctx.primitives['parallax-scroll']) {
      const result = ctx.primitives['parallax-scroll'](root, { intensity: 0.08 });
      appliedPrimitives.push(result);
    }
  }
  resources.primitives = appliedPrimitives;

  // ---- Cleanup -------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Dispose loaded textures
    resources.textures.forEach((t) => {
      if (t && t.dispose) t.dispose();
    });

    // Kill GSAP timelines
    resources.timelines.forEach((tl) => {
      if (tl && tl.kill) tl.kill();
    });

    // Cleanup primitives
    resources.primitives.forEach((p) => {
      if (p && p.cleanup) p.cleanup();
    });

    // Remove from parent if still attached
    if (root.parent) root.parent.remove(root);
  };

  // Position / rotation / scale from config (adapter already applies position)
  if (config.rotation) {
    root.rotation.set(...config.rotation);
  }
  if (config.scale) {
    root.scale.set(...config.scale);
  }

  return root;
}
